// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Direct call to proxiableUUID() after construction (not delegated)
        bytes32 expectedSlot = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        bytes32 result;
        // Use try/catch to ensure the call doesn't revert
        try c.proxiableUUID() returns (bytes32 val) {
            result = val;
        } catch {
            result = bytes32(0);
        }
        // The reference returns the implementation slot; the mutant returns bytes32(0)
        assertTrue(result == expectedSlot, "proxiableUUID should return the implementation slot");
    }
}

