pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // No state setup needed - just call initialize to enable proxiableUUID via onlyProxy
        c.initialize(address(0));

        // proxiableUUID() returns different values: reference returns 0x360894a... (IMPLEMENTATION_SLOT)
        // buggy returns 0x0000...0001
        bytes32 expectedCorrect = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        // The reference C will return this value; the buggy one returns 0x00...01
        // Since we cannot call proxiableUUID() directly on c (it requires notDelegated check that fails on non-proxy),
        // we observe the difference through a revert/behavior difference in upgradeToAndCall
        // But the instruction says to read c's public surface - so we attempt upgradeToAndCall
        // which calls proxiableUUID internally and will revert with UUPSUnsupportedProxiableUUID on buggy version
        bool ok;
        try c.upgradeToAndCall(address(c), "") {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference allows upgrade (returns correct slot), buggy version reverts
        assertTrue(ok);
    }
}

