pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy proxy pointing to the implementation (C itself acts as both logic and proxy for this test)
        // The test uses a minimal ERC1967 proxy to trigger the UUPS upgradeable pattern
        // We use vm.etch to simulate a proxy that delegates to c's code
        // But to stay within cheatcode limitations, we simply call initialize directly on c
        // which is already a UUPSUpgradeable contract; the test directly tests the initializer behavior.

        // Call initialize - the reference sets _initialized to 1, buggy does not.
        c.initialize(address(0x1234));

        // Use low-level call to access the private _getInitializedVersion via the proxy pattern
        // Since we cannot read private storage directly, we observe the effect: in reference, a second call reverts with InvalidInitialization.
        // In buggy version, second call succeeds.
        bool secondSuccess = false;
        try c.initialize(address(0x5678)) {
            secondSuccess = true;
        } catch {
            secondSuccess = false;
        }

        // For the reference, the second call reverts (secondSuccess == false).
        // For the buggy version, the second call succeeds (secondSuccess == true).
        // We assert that the second call FAILS, which is the reference behavior.
        assertTrue(!secondSuccess, "Second initialize should revert (reference behavior)");
    }
}

